"use client";

/**
 * Product launch film: a three-line hook, the name building into a
 * wordmark, the product dropping onto a phone, two features (a screen
 * recording and an agent at work), one sourced number, then the end card.
 * About 31 seconds at 1920 by 1080. Every scene is a Better Design video
 * component, cut together with the whip pan transition.
 *
 * Written by Better Design.
 */
import { linearTiming, TransitionSeries } from "@remotion/transitions";
import { Easing } from "remotion";
import { DeviceDrop } from "@/components/bd-video/device-drop";
import { EndCard } from "@/components/bd-video/end-card";
import { RecordingShot } from "@/components/bd-video/recording-shot";
import { StatCount } from "@/components/bd-video/stat-count";
import { TitleCards } from "@/components/bd-video/title-cards";
import { ToolCalls } from "@/components/bd-video/tool-calls";
import { WordmarkBuild } from "@/components/bd-video/wordmark-build";
import { whipPan } from "@/components/bd-video/transition-whip-pan";
import { type VideoTheme, VideoThemeProvider } from "@/lib/bd-video";

/** Every piece of copy, picture and number the product launch film shows. */
export interface ProductLaunchFilmContent {
  /** The hook: one short statement per card, shown in order. */
  hook: string[];
  /** A word on the last hook card that lands in the primary colour. */
  hookAccent: string;
  /** The product name, built as a wordmark and set on the end card. */
  name: string;
  /** The line beside the phone in the reveal. */
  revealHeadline: string;
  revealSubline: string;
  /** Picture for the phone screen. A placeholder app is drawn when unset. */
  revealScreenshot?: string;
  /** Screen recording (.mp4, .webm, .mov) or a still for the first feature. A placeholder page is drawn when unset. */
  recording?: string;
  /** The capture's pixel size, as ffprobe reports it. */
  recordingSize: { width: number; height: number };
  /** The second feature: each entry reads "tool-name: argument". Four to five fit. */
  tools: string[];
  /** The reply the agent writes once the tools finish. */
  toolAnswer: string;
  /** Label above the agent turn. */
  agentName: string;
  /** The proof number. `source` records where the figure comes from; it is not drawn. */
  stat: { value: number; decimals: number; prefix: string; suffix: string; label: string; source: string };
  /** The call to action on the end card button. */
  cta: string;
  /** The web address under the button. */
  url: string;
}

const DEFAULT_CONTENT: ProductLaunchFilmContent = {
  hook: ["Shipping is the easy part.", "Getting people to notice is hard.", "So we made it simple."],
  hookAccent: "simple",
  name: "Your product",
  revealHeadline: "Everything you need, in your pocket.",
  revealSubline: "Your product, on every screen you own.",
  recordingSize: { width: 1440, height: 900 },
  tools: ["search_docs: billing retries", "read_file: src/billing/retry.ts", "edit_file: src/billing/retry.ts", "run_tests: billing"],
  toolAnswer: "Fixed the retry logic in billing and the test suite passes. The change is ready for your review.",
  agentName: "Agent",
  stat: { value: 12480, decimals: 0, prefix: "", suffix: "", label: "teams use it every week", source: "Replace with your own figure and its source" },
  cta: "Start building today",
  url: "yourproduct.com",
};

export interface ProductLaunchFilmProps {
  content?: Partial<ProductLaunchFilmContent>;
  theme?: Partial<VideoTheme>;
}

/** Frames per scene, in order: hook, name, reveal, recording, agent, proof, end. */
const SCENES = [150, 130, 120, 165, 195, 120, 150] as const;
const CUT = 15;
const cut = () => <TransitionSeries.Transition presentation={whipPan({ direction: "left" })} timing={linearTiming({ durationInFrames: CUT, easing: Easing.bezier(0.7, 0, 0.3, 1) })} />;

/** A product launch film built from Better Design video components. */
export function ProductLaunchFilm({ content, theme }: ProductLaunchFilmProps) {
  const c = { ...DEFAULT_CONTENT, ...content };
  const s = { ...DEFAULT_CONTENT.stat, ...content?.stat };
  return (
    <VideoThemeProvider theme={theme}>
      <TransitionSeries>
        <TransitionSeries.Sequence durationInFrames={SCENES[0]}>
          <TitleCards cards={c.hook} accent={c.hookAccent} holdFrames={44} theme={theme} />
        </TransitionSeries.Sequence>
        {cut()}
        <TransitionSeries.Sequence durationInFrames={SCENES[1]}>
          <WordmarkBuild name={c.name} theme={theme} />
        </TransitionSeries.Sequence>
        {cut()}
        <TransitionSeries.Sequence durationInFrames={SCENES[2]}>
          <DeviceDrop headline={c.revealHeadline} subline={c.revealSubline} screenshot={c.revealScreenshot} theme={theme} />
        </TransitionSeries.Sequence>
        {cut()}
        <TransitionSeries.Sequence durationInFrames={SCENES[3]}>
          <RecordingShot recording={c.recording} captureSize={c.recordingSize} theme={theme} />
        </TransitionSeries.Sequence>
        {cut()}
        <TransitionSeries.Sequence durationInFrames={SCENES[4]}>
          <ToolCalls tools={c.tools} answer={c.toolAnswer} agentName={c.agentName} theme={theme} />
        </TransitionSeries.Sequence>
        {cut()}
        <TransitionSeries.Sequence durationInFrames={SCENES[5]}>
          <StatCount value={s.value} decimals={s.decimals} prefix={s.prefix} suffix={s.suffix} label={s.label} theme={theme} />
        </TransitionSeries.Sequence>
        {cut()}
        <TransitionSeries.Sequence durationInFrames={SCENES[6]}>
          <EndCard name={c.name} cta={c.cta} url={c.url} theme={theme} />
        </TransitionSeries.Sequence>
      </TransitionSeries>
    </VideoThemeProvider>
  );
}

/** Composition settings. The duration is the scenes minus the six 15-frame cuts. */
export const PRODUCT_LAUNCH_FILM = { durationInFrames: 940, fps: 30, width: 1920, height: 1080 } as const;
